// EntityMergePairResult 实体合并结果统计。
//
// 字段语义：
// - images_moved：迁到目标实体名下的图片数
// - images_dropped：预留字段，当前始终为 0（不主动删图，避免误删有效素材）
// - links_moved：迁到目标实体的关联数
// - links_dropped：因目标已存在同一作用域关联而删除的重复关联数
// - candidates_repointed：指向目标的提取候选数
type EntityMergePairResult struct {
	// CandidatesRepointed 重新指向目标实体的提取候选数
	CandidatesRepointed *int `json:"candidates_repointed,omitempty"`

	// EntityType 实体类型：actor/character/scene/prop/costume
	EntityType string `json:"entity_type"`

	// ImagesDropped 丢弃的图片数（当前始终为 0）
	ImagesDropped *int `json:"images_dropped,omitempty"`

	// ImagesMoved 迁移的图片数
	ImagesMoved *int `json:"images_moved,omitempty"`

	// LinksDropped 因重复而删除的关联数
	LinksDropped *int `json:"links_dropped,omitempty"`

	// LinksMoved 迁移的关联数
	LinksMoved *int `json:"links_moved,omitempty"`

	// SourceId 被删除的实体 ID
	SourceId string `json:"source_id"`

	// TargetId 保留的实体 ID
	TargetId string `json:"target_id"`
}

// EntityMergeRequest 实体合并请求：把 source 合并进 target。
type EntityMergeRequest struct {
	// SourceId 被合并掉的实体 ID（合并完成后该记录被删除）
	SourceId string `json:"source_id"`

	// TargetId 保留的实体 ID（图片、关联、候选都会迁移到它）
	TargetId string `json:"target_id"`
}

// EntityMergeResult 实体合并结果（脚本处理中间态）。
type EntityMergeResult struct {
	// Conflicts 发现的冲突/待处理项
	Conflicts *[]string `json:"conflicts,omitempty"`

	// MergeStats 合并统计信息
	MergeStats *map[string]interface{} `json:"merge_stats,omitempty"`

	// MergedLibrary 合并后的实体库
	MergedLibrary EntityLibrary `json:"merged_library"`

	// Notes 合并说明
	Notes *string `json:"notes,omitempty"`
}

// EntityMergerRequest 实体合并请求。
type EntityMergerRequest struct {
	// AllShotExtractions 所有镜头提取结果（ShotElementExtractionResult 的序列化形式）
	AllShotExtractions []map[string]interface{} `json:"all_shot_extractions"`

	// ChapterId 章节 ID（异步任务关联可选）
	ChapterId *string `json:"chapter_id,omitempty"`

	// ConflictResolutions 冲突解决建议列表（可选；用于冲突重试合并）
	ConflictResolutions *[]map[string]interface{} `json:"conflict_resolutions,omitempty"`

	// HistoricalLibrary 历史实体库（可选，用于增量合并）
	HistoricalLibrary *map[string]interface{} `json:"historical_library,omitempty"`

	// PreviousMerge 上一次合并结果（可选；EntityMergeResult 序列化），用于冲突重试合并
	PreviousMerge *map[string]interface{} `json:"previous_merge,omitempty"`

	// ProjectId 项目 ID（异步任务关联可选）
	ProjectId *string `json:"project_id,omitempty"`

	// ScriptDivision 脚本分镜结果（可选；ScriptDivisionResult 序列化），用于定位与统计
	ScriptDivision *map[string]interface{} `json:"script_division,omitempty"`
}

